-- Selection guidance for the eight already-published coaching models.
-- Editorial examples are synthetic, NOT records of client questions.
BEGIN;
ALTER TABLE app_private.coaching_models ADD COLUMN IF NOT EXISTS selection_comment_i18n jsonb;
ALTER TABLE app_private.coaching_models ADD COLUMN IF NOT EXISTS selection_caution_i18n jsonb;
ALTER TABLE app_private.coaching_models ADD COLUMN IF NOT EXISTS example_questions_i18n jsonb;
COMMENT ON COLUMN app_private.coaching_models.selection_comment_i18n IS 'Editorial suggestions: kinds of client questions suited to this model, not a clinical recommendation.';
COMMENT ON COLUMN app_private.coaching_models.selection_caution_i18n IS 'Situations where this model should not be considered sufficient or uniquely best.';
COMMENT ON COLUMN app_private.coaching_models.example_questions_i18n IS 'Synthetic model-fitting client questions in EN/RU/ES. Never real client data.';
UPDATE app_private.coaching_models SET selection_comment_i18n='{"en":"A defined goal, concrete choice or next step: plan realistically from today''s facts.","ru":"Когда сформулирована цель, выбор или следующий шаг: пройти от фактов к плану.","es":"Si hay una meta, decisión o próximo paso definidos."}'::jsonb,selection_caution_i18n='{"en":"Not ideal when the person cannot yet name the topic.","ru":"Не лучший первый шаг, если непонятна сама тема.","es":"No es ideal cuando el tema no está claro."}'::jsonb,example_questions_i18n='{"en":["How do I choose between two jobs?","How do I reach my sales goal?"],"ru":["Как выбрать между двумя работами?","Как достичь цели по продажам?"],"es":["¿Cómo elijo entre dos trabajos?","¿Cómo alcanzo mi meta de ventas?"]}'::jsonb WHERE model_key='grow_v1';
UPDATE app_private.coaching_models SET selection_comment_i18n='{"en":"A mixed or unclear question: identify the main topic before any goal.","ru":"При неопределённом или смешанном запросе: сначала выделить тему.","es":"Si la pregunta es difusa: primero definir el tema."}'::jsonb,selection_caution_i18n='{"en":"For an already precise goal, GROW may be quicker.","ru":"Когда цель уже конкретна, быстрее GROW.","es":"Con una meta precisa, GROW puede ser más rápido."}'::jsonb,example_questions_i18n='{"en":["I don''t know what I really want.","Where do I start if everything is mixed up?"],"ru":["Не знаю, чего хочу.","С чего начать, если всё перепуталось?"],"es":["No sé qué quiero.","¿Por dónde empezar si todo se mezcla?"]}'::jsonb WHERE model_key='tgrow_v1';
UPDATE app_private.coaching_models SET selection_comment_i18n='{"en":"Feeling stuck or unsure: find strengths, past success and small progress.","ru":"Когда человек застрял или сомневается: заметить ресурсы и небольшие успехи.","es":"Si hay bloqueo o dudas: ver recursos y avances pequeños."}'::jsonb,selection_caution_i18n='{"en":"Never force optimism or interpret a self-rating as a clinical test.","ru":"Не требовать оптимизма и не трактовать шкалу как диагностику.","es":"No forzar optimismo ni interpretar una escala como test clínico."}'::jsonb,example_questions_i18n='{"en":["What resources do I have when I feel stuck?","How can I regain confidence?"],"ru":["На что опереться, если я застрял(а)?","Как вернуть уверенность?"],"es":["¿Con qué recursos cuento si estoy bloqueado?","¿Cómo recuperar confianza?"]}'::jsonb WHERE model_key='oskar_v1';
UPDATE app_private.coaching_models SET selection_comment_i18n='{"en":"A difficult conversation, tension, boundaries or relationship conflict.","ru":"Сложный разговор, напряжение, границы и конфликт в отношениях.","es":"Conversaciones difíciles, tensión, límites o conflicto."}'::jsonb,selection_caution_i18n='{"en":"Not sufficient for violence, coercion or acute danger.","ru":"Не заменяет защиту при насилии, принуждении или острой опасности.","es":"No sirve como única ayuda ante violencia, coerción o peligro."}'::jsonb,example_questions_i18n='{"en":["How can I talk with my partner without fighting?","How do I raise a difficult issue with my boss?"],"ru":["Как поговорить с партнёром без ссоры?","Как обсудить сложную тему с начальником?"],"es":["¿Cómo hablar con mi pareja sin pelear?","¿Cómo tratar un tema difícil con mi jefe?"]}'::jsonb WHERE model_key='clear_v1';
UPDATE app_private.coaching_models SET selection_comment_i18n='{"en":"Leadership, workplace habits and performance changes with an action plan.","ru":"Лидерство, рабочие привычки, результативность и практический план.","es":"Liderazgo, hábitos de trabajo y mejora del desempeño."}'::jsonb,selection_caution_i18n='{"en":"Not a substitute for labor, legal or financial advice.","ru":"Не заменяет кадровую, правовую или финансовую консультацию.","es":"No sustituye asesoría laboral, legal o financiera."}'::jsonb,example_questions_i18n='{"en":["How can I delegate better?","What should I change in leading my team?"],"ru":["Как лучше делегировать?","Что поменять в управлении командой?"],"es":["¿Cómo delegar mejor?","¿Qué cambiar al dirigir mi equipo?"]}'::jsonb WHERE model_key='fuel_v1';
UPDATE app_private.coaching_models SET selection_comment_i18n='{"en":"Looking for a small shift, exceptions to the problem and what already works.","ru":"Если нужен небольшой сдвиг: исключения, удачные моменты, работающие решения.","es":"Para un cambio pequeño: excepciones y lo que ya funciona."}'::jsonb,selection_caution_i18n='{"en":"This is coaching reflection, not solution-focused psychotherapy.","ru":"Это коучинговая адаптация, не психотерапия.","es":"Es coaching, no psicoterapia centrada en soluciones."}'::jsonb,example_questions_i18n='{"en":["How can I move forward a little when stuck?","When did I handle it better?"],"ru":["Как чуть сдвинуться с места?","Когда у меня уже получалось лучше?"],"es":["¿Cómo avanzar un poco si estoy atascado?","¿Cuándo lo logré mejor?"]}'::jsonb WHERE model_key='solution_focus_v1';
UPDATE app_private.coaching_models SET selection_comment_i18n='{"en":"Procrastination, habits and a feasible wish blocked by an internal reaction.","ru":"Прокрастинация, привычки и посильное желание с внутренним препятствием.","es":"Procrastinación, hábitos y un deseo posible con obstáculo interno."}'::jsonb,selection_caution_i18n='{"en":"Full WOOP needs a personally formulated if–then plan, not only button choices.","ru":"Полноценный WOOP требует личного плана «если — то», не только кнопок.","es":"WOOP completo requiere un plan personal «si — entonces»."}'::jsonb,example_questions_i18n='{"en":["Why do I keep postponing writing?","How can I start exercising regularly?"],"ru":["Почему всё время откладываю задачу?","Как начать заниматься регулярно?"],"es":["¿Por qué sigo posponiendo tareas?","¿Cómo empezar a entrenar regularmente?"]}'::jsonb WHERE model_key='woop_v1';
UPDATE app_private.coaching_models SET selection_comment_i18n='{"en":"Creative change, strengths-based reinvention, new project or shared team vision.","ru":"Творческие перемены, сильные стороны, новый проект или образ будущего команды.","es":"Cambios creativos, fortalezas, nuevos proyectos y visión del equipo."}'::jsonb,selection_caution_i18n='{"en":"Originally an organizational method; individual coaching here is an adaptation.","ru":"Изначально метод для организаций; индивидуальная версия является адаптацией.","es":"Es originalmente organizacional; esta sesión es una adaptación individual."}'::jsonb,example_questions_i18n='{"en":["How do I build a project from my strengths?","What future could our team create?"],"ru":["Как построить проект на сильных сторонах?","Какое будущее создать с командой?"],"es":["¿Cómo crear un proyecto desde mis fortalezas?","¿Qué futuro puede crear nuestro equipo?"]}'::jsonb WHERE model_key='appreciative_5d_v1';
-- Keep these guidance columns nullable: future independently authored coaching
-- models may be seeded before they receive their editorial selection comments.
UPDATE app_private.coaching_models SET selection_comment_i18n='{"en":"Best for a values-based personal aim: move from inner desire through strengths to a feasible act.","ru":"Подходит для вопроса о желании, ценностях, уникальных ресурсах и действии.","es":"Para una meta personal basada en deseo, valores y recursos."}'::jsonb,selection_caution_i18n='{"en":"An original author-inspired reflection; not evidence for claims about historical Egyptian practices.","ru":"Авторская адаптация, не доказательство конкретной исторической египетской практики.","es":"Adaptación editorial, no evidencia de prácticas históricas concretas."}'::jsonb,example_questions_i18n='{"en":["How can I connect my wish with my values?","Which strengths support my goal?"],"ru":["Как связать желание с моими ценностями?","Какие ресурсы поддержат мою цель?"],"es":["¿Cómo unir mi deseo y mis valores?","¿Qué fortalezas me ayudan?"]}'::jsonb WHERE model_key='egyptian_goal_planning_v1';
UPDATE app_private.coaching_models SET selection_comment_i18n='{"en":"Best for a creative or career question involving courage, meaning and an ideal image of the future.","ru":"Подходит для размышления о смысле, воле, идеальном образе и творческом или карьерном выборе.","es":"Para decisiones sobre sentido, valor y visión de futuro."}'::jsonb,selection_caution_i18n='{"en":"A contemporary coaching reinterpretation, not a historically validated ancient procedure.","ru":"Современная коучинговая интерпретация, не исторически валидированная процедура.","es":"Reinterpretación moderna, no método antiguo validado históricamente."}'::jsonb,example_questions_i18n='{"en":["How can I act courageously toward my ideal?","How can I find meaning in a career change?"],"ru":["Как действовать смело ради идеала?","В чём смысл смены профессии?"],"es":["¿Cómo actuar con valor hacia mi ideal?","¿Qué sentido tiene un cambio de carrera?"]}'::jsonb WHERE model_key='greek_goal_planning_v1';
COMMIT;
